fn get_first_elements(lst: Vec<Vec<i32>>) -> Vec<i32> {
    // Pre-allocate the result vector with the same length as the outer list
    let mut result = Vec::with_capacity(lst.len());

    // For each inner vector, push its first element into `result`
    for inner in lst {
        // We assume each inner vector is non-empty, so indexing at 0 is safe.
        result.push(inner[0]);
    }

    result
}

// Example usage and basic test
fn main() {
    let data = vec![
        vec![10, 20, 30],
        vec![-1, -2],
        vec![42],
        vec![0, 1, 2, 3],
    ];

    let firsts = get_first_elements(data);
    assert_eq!(firsts, vec![10, -1, 42, 0]);
    println!("First elements: {:?}", firsts);
}